package pdfgrab_test

import (
	"errors"
	"testing"

	"github.com/hallelx2/pdfgrab"
)

// TestEncryptedDocuments pins what pdfgrab does with encrypted PDFs, both
// AES-256 and generated by scripts/gen_encrypted_fixtures.sh.
//
// A document with only an owner password has an empty user password, so
// pdfcpu decrypts it on open and it reads like any other file. A document
// with a user password cannot be opened without it, and pdfgrab has no way
// to take one, so Open must say so with ErrEncrypted rather than a generic
// parse failure.
func TestEncryptedDocuments(t *testing.T) {
	t.Run("owner password only opens and reads", func(t *testing.T) {
		doc, err := pdfgrab.OpenFile("testdata/encrypted/owner-password-only.pdf")
		if err != nil {
			t.Fatalf("OpenFile: %v", err)
		}
		defer closeDoc(t, doc)
		page, err := doc.Page(1)
		if err != nil {
			t.Fatalf("Page(1): %v", err)
		}
		tables, err := page.ExtractTables(pdfgrab.DefaultTableSettings())
		if err != nil {
			t.Fatalf("ExtractTables: %v", err)
		}
		if len(tables) != 1 || len(tables[0].Rows) == 0 || tables[0].Rows[0][0] != "Name" {
			t.Fatalf("got %d tables, want the 2x3 fixture table starting with \"Name\": %+v", len(tables), tables)
		}
	})

	t.Run("user password returns ErrEncrypted", func(t *testing.T) {
		doc, err := pdfgrab.OpenFile("testdata/encrypted/user-password.pdf")
		if err == nil {
			_ = doc.Close()
			t.Fatal("OpenFile succeeded on a document that needs a user password")
		}
		if !errors.Is(err, pdfgrab.ErrEncrypted) {
			t.Fatalf("err = %v, want ErrEncrypted", err)
		}
	})
}
